INSERT INTO `simulation_scenarios` (`id`, `scenario_code`, `name`, `category`, `expected_result`, `fault_start_progress`, `fault_end_progress`, `affected_position`, `parameters_json`, `description`, `is_enabled`, `created_at`, `updated_at`) VALUES
  (1, 'NORMAL', 'Normal flight', 'NORMAL', 'SUCCESS', NULL, NULL, 'NONE', '{}', 'All simulated health metrics remain within the project normal envelope.', TRUE, '2026-07-02 09:00:00', '2026-09-19 10:00:00'),
  (2, 'LOW_BATTERY', 'Low battery reserve', 'POWER', 'RETURN_TO_HOME', 62, 100, 'CENTER_REAR', '{"targetEndPercent":8}', 'Battery reserve drops through warning and critical thresholds, triggering return-to-home.', TRUE, '2026-07-02 09:00:00', '2026-09-19 10:00:00'),
  (3, 'BATTERY_VOLTAGE_DROP', 'Battery voltage sag', 'POWER', 'FAILED', 52, 100, 'CENTER_REAR', '{"warningV":14,"criticalV":13.2}', 'Pack voltage sags abnormally under load even though percentage remains non-zero.', TRUE, '2026-07-02 09:00:00', '2026-09-19 10:00:00'),
  (4, 'BATTERY_OVERHEAT', 'Battery overheating', 'THERMAL', 'RETURN_TO_HOME', 45, 100, 'CENTER_REAR', '{"warningC":50,"criticalC":60}', 'Battery temperature rises beyond project warning and critical thresholds.', TRUE, '2026-07-02 09:00:00', '2026-09-19 10:00:00'),
  (5, 'MOTOR_OVERHEAT', 'Motor overheating', 'THERMAL', 'RETURN_TO_HOME', 42, 100, 'RUNTIME_SELECTED', '{"allowedPositions":["FRONT_LEFT","FRONT_RIGHT","REAR_LEFT","REAR_RIGHT"],"warningC":70,"criticalC":80}', 'One runtime-selected motor temperature rises abnormally and requires an early return.', TRUE, '2026-07-02 09:00:00', '2026-09-19 10:00:00'),
  (6, 'PROPELLER_DAMAGE', 'Propeller damage suspected', 'PROPULSION', 'FAILED', 50, 100, 'RUNTIME_SELECTED', '{"allowedPositions":["FRONT_LEFT","FRONT_RIGHT","REAR_LEFT","REAR_RIGHT"],"rpmImbalanceWarningPercent":15,"rpmImbalanceCriticalPercent":25,"vibrationCriticalG":2.5}', 'A runtime-selected arm develops RPM loss plus excessive vibration and is treated as suspected propeller damage.', TRUE, '2026-07-02 09:00:00', '2026-09-19 10:00:00'),
  (7, 'GPS_LOSS', 'Temporary GNSS loss', 'NAVIGATION', 'RETURN_TO_HOME', 48, 61, 'TOP_CENTER', '{"lostSamples":20}', 'GNSS data becomes unavailable, then recovers before landing.', TRUE, '2026-07-02 09:00:00', '2026-09-19 10:00:00'),
  (8, 'SIGNAL_LOSS', 'Temporary communication loss', 'COMMUNICATION', 'RETURN_TO_HOME', 55, 57, 'NONE', '{"lostSamples":6}', 'Control-link signal falls to zero for less than the heartbeat-timeout window, then recovers before landing.', TRUE, '2026-07-02 09:00:00', '2026-09-19 10:00:00'),
  (9, 'UNEXPECTED_OFFLINE', 'Unexpected heartbeat timeout', 'COMMUNICATION', 'FAILED', 58, 100, 'NONE', '{"heartbeatTimeoutSeconds":15}', 'The backend stops receiving heartbeats while the drone is online or in flight; this is different from a user-requested power-off.', TRUE, '2026-07-02 09:00:00', '2026-09-19 10:00:00');
